/**
 * Returns a concise original computational summary for a problem.
 * @param {string} slug - Problem slug in kebab-case
 * @param {string} [fallback] - Optional fallback text
 * @returns {string} The problem summary
 */
export function getProblemSummary(slug, fallback = 'Explore the algorithm step by step with interactive inputs and state transitions.') {
  return (slug && PROBLEM_SUMMARIES[slug]) || fallback;
}
